\set ON_ERROR_STOP on
BEGIN;
INSERT INTO public.pos_products (id,license_id,name,name_key,price,cost,stock,track_stock,batch_management) VALUES ('lab-batch-product','00000000-0000-0000-0000-000000000001','Synthetic batch product','synthetic batch product',10,4,20,true,'{"enabled":true}');
INSERT INTO public.pos_product_batches (id,license_id,product_id,stock,cost,price) VALUES ('lab-batch-real','00000000-0000-0000-0000-000000000001','lab-batch-product',20,4,10);
INSERT INTO public.pos_restaurant_orders (id,license_id,local_order_id,table_label,status,fulfillment_status,subtotal,total,updated_at) VALUES ('lab-batch-order-row','00000000-0000-0000-0000-000000000001','lab-batch-order','Lab batch','ready','ready',20,20,'2026-10-01T00:00:00Z');
COMMIT;
DO $test$ DECLARE h text; a jsonb; b jsonb; BEGIN
h:=private.financial_operation_hash('sale.cashier_inventory',private.canonical_financial_request_v1('sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-batch-order","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-batch-sale-item","product_id":"lab-batch-product","product_name":"Synthetic batch product","batch_id":"lab-batch-real","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-batch-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-batch-order","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb),'admin:00000000-0000-0000-0000-0000000000aa','lab-cash-a','lab-station-a');
a:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-batch-key',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-batch-order","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-batch-sale-item","product_id":"lab-batch-product","product_name":"Synthetic batch product","batch_id":"lab-batch-real","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-batch-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-batch-order","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
b:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-batch-key',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-batch-order","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-batch-sale-item","product_id":"lab-batch-product","product_name":"Synthetic batch product","batch_id":"lab-batch-real","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-batch-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-batch-order","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
IF a IS DISTINCT FROM b OR (a->>'success')::boolean IS DISTINCT FROM true OR (SELECT stock FROM public.pos_product_batches WHERE id='lab-batch-real')<>18 OR (SELECT stock FROM public.pos_products WHERE id='lab-batch-product')<>18 OR (SELECT count(*) FROM public.pos_inventory_movements WHERE product_id='lab-batch-product' AND batch_id='lab-batch-real' AND quantity=2)<>1 OR NOT (SELECT checkout_closed_at IS NOT NULL AND payment_status='paid' FROM public.pos_restaurant_orders WHERE id='lab-batch-order-row') THEN RAISE EXCEPTION 'BATCH_EFFECTS_MISMATCH'; END IF;
END $test$;
SELECT 'PASS_REAL_BATCH_SALE_AND_REPLAY' result;